export const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function validateSnapshot(d){
  if(d?.username!=='onurhuseyinkocak.ai'||d.source!=='Meta Graph API'||d.days!==30||!Number.isFinite(Date.parse(d.measuredAt))||!Number.isSafeInteger(d.followers)||d.followers<0)throw Error('Invalid creator snapshot');
  if(Date.parse(d.endDate)-Date.parse(d.startDate)!==29*86400000)throw Error('Invalid metric period');
  for(const n of ['views','reach','comments','likes','saves','shares','total_interactions'])if(typeof d.metrics?.[n]!=='number'||!Number.isFinite(d.metrics[n])||d.metrics[n]<0)throw Error('Missing verified metric');
  if(d.campaigns?.length!==2||d.campaigns.map(p=>p.brand).join(',')!=='Brantial,Mostdomain')throw Error('Unexpected campaign');
  if(d.carousels?.length!==3||d.reels?.length!==3)throw Error('Unexpected showcase');
  for(const p of [...d.campaigns,...d.carousels,...d.reels])if(!/^\d+$/.test(p.id)||!/^https:\/\/www\.instagram\.com\/(p|reel)\/[\w-]+\/$/.test(p.permalink)||!/^assets\/creator\/\d+\.jpg$/.test(p.poster)||!Number.isFinite(Date.parse(p.publishedAt)))throw Error('Untrusted portfolio media');
  for(const p of d.campaigns)if(!/^assets\/creator\/\d+\.mp4$/.test(p.video))throw Error('Untrusted campaign video');
  return d;
}
