  const head=`<!doctype html><html lang="${lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(c.title)}</title><meta name="description" content="${esc(c.description)}"><meta name="robots" content="index,follow,max-image-preview:large">${themes}<link rel="canonical" href="${url}"><link rel="alternate" hreflang="en" href="${site}/"><link rel="alternate" hreflang="tr" href="${site}/tr/"><link rel="alternate" hreflang="x-default" href="${site}/"><meta property="og:type" content="website"><meta property="og:site_name" content="Onur Hüseyin Koçak"><meta property="og:locale" content="${lang==='tr'?'tr_TR':'en_US'}"><meta property="og:title" content="${esc(c.title)}"><meta property="og:description" content="${esc(c.description)}"><meta property="og:url" content="${url}">${social}<link rel="icon" href="/assets/favicon.svg">${fonts}<link rel="stylesheet" href="/creator.css"><script type="application/ld+json">${JSON.stringify(ld).replace(/</g,'\\u003c')}</script><script defer src="/creator.js"></script></head>`;
  const header=`<body><a class="skip" href="#main">${lang==='tr'?'İçeriğe geç':'Skip to content'}</a>
<header class="header"><div class="wrap header-in"><a class="wordmark" href="${home}">Onur H. Koçak<span>Tech UGC</span></a><nav aria-label="${lang==='tr'?'Ana gezinme':'Main navigation'}">${['work','results','rates','about'].map((id,i)=>`<a href="#${id}">${c.nav[i]}</a>`).join('')}</nav><div class="header-actions"><a class="language" href="${c.other}" lang="${lang==='tr'?'en':'tr'}" hreflang="${lang==='tr'?'en':'tr'}">${c.language}</a><a class="button small" href="#brief">${c.cta}</a></div></div></header>`;
  const hero=`<section class="hero wrap"><div class="hero-copy"><p class="eyebrow">${c.kicker}</p><h1>${c.h}</h1><p class="intro">${c.intro}</p><div class="hero-actions"><a class="button" href="#brief">${c.cta} ${go}</a><a class="text-link" href="#rates">${c.pricecta}</a></div></div>
<figure class="stack" data-tilt><div class="stack-scene"><img class="stack-cover stack-a" src="${poster(d.campaigns[0])}" alt="${esc(d.campaigns[0].brand+' Reel')}" width="720" height="1280" decoding="async" fetchpriority="low"><img class="stack-portrait" src="/assets/img/onur-900.webp" srcset="/assets/img/onur-900.webp 900w, /assets/img/onur-1170.webp 1170w" sizes="(max-width: 760px) 92vw, 520px" alt="${esc(c.who+', '+c.role)}" width="900" height="520" fetchpriority="high"><img class="stack-cover stack-b" src="${poster(d.campaigns[1])}" alt="${esc(d.campaigns[1].brand+' Reel')}" width="720" height="1280" decoding="async" fetchpriority="low"></div><figcaption><strong>${c.who}</strong><span>${c.role}</span><span>${c.availability}</span></figcaption></figure></section>
<section class="proof wrap" aria-label="${esc(c.partners)}"><div class="proof-brands"><p class="label">${c.partners}</p>${d.campaigns.map(p=>plate(p.brand,'#case-'+p.id)).join('')}</div><dl class="proof-stats">${[['views',d.metrics.views],['reach',d.metrics.reach],['followers',d.followers]].map(([k,v])=>`<div><dt>${c.metric[k]}</dt><dd data-account="${k}">${num(v,lang)}</dd></div>`).join('')}</dl><p class="proof-note"><a href="#results">${c.proofnote}</a></p></section>`;
  const work=`<section id="work" class="work wrap" aria-labelledby="work-title"><div class="section-top"><h2 id="work-title">${c.work}</h2><p class="section-description">${c.worksub}</p></div>${d.campaigns.map(p=>{const t=c.campaigns[p.brand];return `<article class="case" id="case-${p.id}" aria-labelledby="case-title-${p.id}"><div class="case-media"><video controls playsinline preload="none" poster="${poster(p)}"${has(p.video.replace(/\.mp4$/,'-preview.mp4'))?` data-preview="/${p.video.replace(/\.mp4$/,'-preview.mp4')}"`:''} aria-label="${esc(p.brand+', '+c.video)}" width="540" height="960"><source src="/${p.video}" type="video/mp4"><a href="${p.permalink}">${c.original}</a></video><button class="sound" type="button" aria-label="${esc(p.brand+': '+c.sound)}" hidden>${c.sound}</button></div><div class="case-body"><div class="case-head">${plate(p.brand)}<p class="case-tags">${t[2]}</p></div><h3 id="case-title-${p.id}">${t[0]}</h3><dl class="case-story"><div><dt>${c.brief}</dt><dd>${t[1]}</dd></div><div><dt>${c.delivered}</dt><dd>${t[3]} ${c.published} <time datetime="${p.publishedAt}">${date(p.publishedAt,lang)}</time>. ${c.disclosed}</dd></div></dl><dl class="case-metrics">${['views','reach','saved','shares','likes','comments'].map(k=>`<div><dt>${label(k)}</dt><dd>${post(p,k)}</dd></div>`).join('')}</dl><p class="source">${c.lifetime}. Meta Graph API, ${measured}.</p><a class="text-link" href="${p.permalink}"${ext}>${c.original} ${out}</a></div></article>`}).join('')}<p class="nudge">${c.nudge} <a class="text-link" href="#brief">${c.cta} ${go}</a></p></section>`;
  const results=`<section id="results" class="results wrap" aria-labelledby="results-title"><div class="section-top"><h2 id="results-title">${c.results}</h2><p class="period">@onurhuseyinkocak.ai<br>${c.period}<br><time data-period="startDate" datetime="${d.startDate}">${date(d.startDate,lang)}</time> - <time data-period="endDate" datetime="${d.endDate}">${date(d.endDate,lang)}</time></p></div><div class="metric-layout"><div class="lead-metric"><span>${c.metric.views}</span><strong data-account="views">${num(d.metrics.views,lang)}</strong><div class="reach-chart">${chart(d.daily,c.daily)}<span data-reach-caption data-label="${c.daily}">${c.daily} · ${date(d.daily[0].date,lang)} - ${date(d.daily.at(-1).date,lang)}</span></div></div><dl class="metrics">${stats.slice(1).map(([key,value])=>`<div><dt>${c.metric[key]}</dt><dd data-account="${key}">${num(value,lang)}</dd></div>`).join('')}</dl></div><p class="source">${c.source} ${c.measured}: <time data-measured datetime="${d.measuredAt}">${date(d.measuredAt,lang)}</time>. ${c.statnote}</p></section>`;
  const shelf=(items,name,kind)=>`<div class="shelf shelf-${kind}"><h3>${name}</h3><ol>${items.map(p=>`<li>${textOnly.has(p.id)?`<a class="cover cover-text" href="${p.permalink}"${ext}><span>${esc(title(p,lang))}</span></a>`:`<a class="cover" href="${p.permalink}"${ext}><img src="${poster(p)}" alt="${esc(title(p,lang)+', Instagram '+(kind==='reel'?'Reel':'carousel')+(lang==='tr'?' kapağı':' cover'))}" width="720" height="${kind==='reel'?1280:900}" loading="lazy" decoding="async"></a>`}<div class="rank"><p class="rank-title">${esc(title(p,lang))}</p><p class="rank-views">${post(p,'views')} <small>${c.metric.views.toLowerCase()}</small></p><dl class="rank-metrics">${['saved','shares'].map(k=>`<div><dt>${label(k)}</dt><dd>${post(p,k)}</dd></div>`).join('')}</dl>${typeof p.metrics.follows==='number'?`<p class="follows">+${post(p,'follows')} ${c.follow}</p>`:''}<p class="rank-date"><time datetime="${p.publishedAt}">${date(p.publishedAt,lang)}</time></p></div></li>`).join('')}</ol></div>`;
