  const craft=`<section id="craft" class="craft wrap" aria-labelledby="craft-title"><div class="section-top"><h2 id="craft-title">${c.craft}</h2><p class="section-description">${c.craftsub}</p></div><div class="craft-grid"><figure class="craft-film"><video controls muted loop playsinline preload="none" data-autoplay poster="/assets/craft/promtable-3d.webp" aria-label="${esc(c.craftitems[0][1])}" width="540" height="960"><source src="/assets/craft/promtable-3d.mp4" type="video/mp4"></video><figcaption><strong>${c.craftitems[0][0]}</strong><span>${c.craftitems[0][1]}</span></figcaption></figure><figure class="craft-web"><img src="/assets/craft/promtable-web.webp" alt="${esc(c.craftitems[1][1])}" width="1280" height="800" loading="lazy" decoding="async"><figcaption><strong>${c.craftitems[1][0]}</strong><span>${c.craftitems[1][1]}</span><a class="text-link" href="https://promtable.com"${ext}>promtable.com ${out}</a></figcaption></figure><figure class="craft-app"><img src="/assets/craft/promtable-ios.webp" alt="${esc(c.craftitems[2][1])}" width="720" height="1566" loading="lazy" decoding="async"><figcaption><strong>${c.craftitems[2][0]}</strong><span>${c.craftitems[2][1]}</span></figcaption></figure></div><p class="source">${c.craftnote}</p></section>`;
  const process=`<section id="process" class="process wrap" aria-labelledby="process-title"><div class="section-top"><h2 id="process-title">${c.process}</h2><p class="section-description">${c.processsub}</p></div><ol class="steps">${c.steps.map(([name,text])=>`<li><h3>${name}</h3><p>${text}</p></li>`).join('')}</ol></section>`;
  const rates=`<section id="rates" class="rates wrap" aria-labelledby="rates-title"><div class="section-top"><h2 id="rates-title">${c.rates}</h2><p class="section-description">${c.ratessub}</p></div><div class="rate-list">${c.packages.map(([name,price,desc,included],i)=>`<article class="rate"><div class="rate-what"><h3>${name}</h3><p>${desc}</p><ul>${included.map(s=>`<li>${s}</li>`).join('')}</ul></div><p class="rate-price"><span>$${price}</span> <small>USD</small></p><a class="button" href="#brief" data-format="${i}">${c.book[i]} ${go}</a></article>`).join('')}</div><details class="rights"><summary>${c.rights} <span aria-hidden="true">+</span></summary><ul>${c.terms.map(s=>`<li>${s}</li>`).join('')}</ul></details><p class="source">${c.terms[0]}</p><a class="text-link" href="/Onur_Huseyin_Kocak_UGC_Rate_Card_2026.pdf" download>${c.pdf} <span class="arr" aria-hidden="true">↓</span></a></section>`;
  const faq=`<section id="faq" class="questions wrap" aria-labelledby="faq-title"><div class="section-top"><h2 id="faq-title">${c.faqtitle}</h2></div><div class="faq">${c.faq.map(([q,a])=>`<details><summary>${q} <span aria-hidden="true">+</span></summary><p>${a}</p></details>`).join('')}</div></section>`;
