  const brief=`<section id="brief" class="contact" aria-labelledby="brief-title"><div class="wrap contact-grid"><div><h2 id="brief-title">${c.contact}</h2><p>${c.contactsub}</p><div class="contact-links"><a class="text-link" href="${mail()}">info@vibecodingturkey.com ${go}</a><a class="text-link" href="${dm}"${ext}>${c.dm} ${out}</a></div></div><form id="brief-form"><label>${c.brand}<input name="brand" autocomplete="organization" required maxlength="120"></label><label>${c.product}<input name="product" type="url" inputmode="url" autocomplete="url" required maxlength="2000" placeholder="https://"></label><div class="form-row"><label>${c.format}<select name="format">${c.packages.map(([n,p])=>`<option>${n}, $${p} USD</option>`).join('')}</select></label><label>${c.usage}<select name="usage">${c.usages.map(n=>`<option>${n}</option>`).join('')}</select></label></div><label>${c.deadline}<input name="deadline" autocomplete="off" maxlength="160"></label><label>${c.notes}<textarea name="notes" rows="3" autocomplete="off" maxlength="1600"></textarea></label><button class="button" type="submit">${c.draft} ${go}</button><p id="form-status" class="form-note" role="status">${c.draftnote}</p><a id="draft-link" class="text-link" hidden>${c.email} ${go}</a></form></div></section>`;
  const footer=`<footer class="wrap footer"><div><strong>Onur Hüseyin Koçak</strong><p>${c.footer}</p></div><div class="footer-links"><a href="https://vibecodingturkey.com">Vibe Coding Turkey</a><a href="https://academy.vibecodingturkey.com/kaynaklar">VCT Academy</a><a href="${c.other}" lang="${lang==='tr'?'en':'tr'}" hreflang="${lang==='tr'?'en':'tr'}">${c.language}</a>${legalLinks(lang)}</div><span>© ${new Date(d.measuredAt).getUTCFullYear()} Onur Hüseyin Koçak</span></footer><div class="dock" data-dock><span>${c.pricecta}</span><a class="button small" href="#brief">${c.cta}</a></div></body></html>`;
