  const ratesBlock=`<h2>Rates</h2><ul>${en.packages.map(([name,price,desc])=>`<li><strong>${name}: $${price} USD.</strong> ${desc}</li>`).join('')}</ul><p>${en.ratessub} ${en.terms[0]} <a href="/#rates">Full rates</a> · <a href="/usage-rights/">Usage rights</a> · <a href="/Onur_Huseyin_Kocak_UGC_Rate_Card_2026.pdf">Rate card (PDF)</a></p>`;
